#include "../common.h"
static char sq[25];static void build(char *key){int used[26]={0},n=0;used['J'-'A']=1;upper_letters(key);for(int pass=0;pass<2;pass++){char *p=pass?"ABCDEFGHIJKLMNOPQRSTUVWXYZ":key;for(;*p;p++)if(isalpha((unsigned char)*p)){char c=*p=='J'?'I':*p;if(!used[c-'A']){used[c-'A']=1;sq[n++]=c;}}}}static void pos(char c,int *r,int *col){if(c=='J')c='I';for(int i=0;i<25;i++)if(sq[i]==c){*r=i/5;*col=i%5;return;}}int main(void){char key[100],msg[500],p[1000];printf("Keyword: ");scanf("%99s",key);getchar();printf("Message: ");fgets(msg,sizeof msg,stdin);build(key);int n=0;for(int i=0;msg[i];){if(!isalpha((unsigned char)msg[i])){i++;continue;}char a=toupper(msg[i++]);if(a=='J')a='I';char b='X';while(msg[i]&&!isalpha((unsigned char)msg[i]))i++;if(msg[i]){char t=toupper(msg[i]);if(t=='J')t='I';if(t!=a){b=t;i++;}}p[n++]=a;p[n++]=b;}if(n%2)p[n++]='X';for(int i=0;i<n;i+=2){int r1,c1,r2,c2;pos(p[i],&r1,&c1);pos(p[i+1],&r2,&c2);if(r1==r2){p[i]=sq[r1*5+(c1+1)%5];p[i+1]=sq[r2*5+(c2+1)%5];}else if(c1==c2){p[i]=sq[((r1+1)%5)*5+c1];p[i+1]=sq[((r2+1)%5)*5+c2];}else{p[i]=sq[r1*5+c2];p[i+1]=sq[r2*5+c1];}}p[n]=0;printf("Ciphertext: %s\n",p);}
